let raw = $('AIAgent').first().json.output ?? $('AIAgent').first().json.text ?? '';
if (typeof raw !== 'string') {
  const body = $('Webhook').first().json.body;
  return [{ json: { contenido_generado: raw, dba_referenciados: raw?.dba_citado ? [raw.dba_citado] : [], docente_id: body.docente_id, area: body.area, grados: body.grados, tema: body.tema, tipo_actividad: body.tipo_actividad || null, agente_usado: 'GPT-4o-Mini + RAG' } }];
}
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const first = raw.indexOf('{');
const last = raw.lastIndexOf('}');
if (first !== -1 && last !== -1) raw = raw.substring(first, last + 1);
raw = raw.replace(/\\\(/g, '$').replace(/\\\)/g, '$').replace(/\\\[/g, '$$').replace(/\\\]/g, '$$');
function fixInvalidJsonEscapes(jsonStr) { return jsonStr.replace(/\\(?!["\\/bfnrtu])/g, '\\\\'); }
let contenido;
try { contenido = JSON.parse(fixInvalidJsonEscapes(raw)); } catch (e) { throw new Error('JSON de planeación inválido: ' + e.message); }
const body = $('Webhook').first().json.body;
return [{ json: { contenido_generado: contenido, dba_referenciados: contenido.dba_citado ? [contenido.dba_citado] : [], docente_id: body.docente_id, area: body.area, grados: body.grados, tema: body.tema, tipo_actividad: body.tipo_actividad || null, agente_usado: 'GPT-4o-Mini + RAG' } }];
